{
  "components": [
    {
      "type": "claim",
      "quote": "In Switzerland more than 40% of energy consumption and about a third of climate-damaging CO2 emissions are attributable to the building industry.",
      "gist": "Swiss building industry accounts for over 40% of energy use and ~33% of CO2 emissions."
    },
    {
      "type": "obligation",
      "quote": "Through the Building Programme the Federal Government and the cantons hope to reduce energy consumption considerably in the Swiss building industry and also lower CO2 emissions.",
      "gist": "Government aims to reduce energy use and CO2 emissions via the Building Programme."
    },
    {
      "type": "obligation",
      "quote": "This is why they subsidise the cost of the energy-saving renovation of buildings.",
      "gist": "Government subsidizes energy-saving building renovations."
    },
    {
      "type": "claim",
      "quote": "The programme is partially financed by revenues from the CO2 levy on fuels.",
      "gist": "Building Programme partly funded by CO2 fuel levy revenues."
    },
    {
      "type": "claim",
      "quote": "With the Energy Strategy more money is available from the CO2 levy for the Building Programme.",
      "gist": "Energy Strategy increases CO2 levy funding for Building Programme."
    }
  ]
}
